def kill_process(pid):
    try:
        os.kill(pid, signal.SIGTERM)
        print(f"Process with PID {pid} has been terminated.")
    except OSError as err:
        if err.errno != errno.ENOENT:
            raise
        print(f"Process with PID {pid} does not exist.")

